package com.bank.jdbc;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// Simulates a database table: holds rows by id and records every SQL query received.
class FakeJdbcTable {
    private static final Logger log = Logger.getLogger(FakeJdbcTable.class.getName());

    private final int rowCount;
    private final ConcurrentLinkedQueue<String> executedQueries = new ConcurrentLinkedQueue<>();
    private final List<int[]> written = new ArrayList<>(); // simulated written rows
    private final AtomicInteger roundTrips = new AtomicInteger();

    FakeJdbcTable(int rowCount) { this.rowCount = rowCount; }

    // Returns ids in [lo, hi) — simulates a ranged SELECT. fetchsize counts round trips.
    List<Integer> query(String sql, int lo, int hi, int fetchsize) {
        executedQueries.add(sql);
        List<Integer> rows = new ArrayList<>();
        for (int id = Math.max(1, lo); id < Math.min(hi, rowCount + 1); id++) rows.add(id);
        int trips = (int) Math.ceil(rows.size() / (double) fetchsize);
        roundTrips.addAndGet(Math.max(trips, 1));
        return rows;
    }

    synchronized void insertBatch(List<int[]> batch) { written.addAll(batch); }

    int executedQueryCount() { return executedQueries.size(); }
    int roundTrips() { return roundTrips.get(); }
    int writtenRows() { return written.size(); }
    List<String> queries() { return new ArrayList<>(executedQueries); }
}
