package com.bank.jdbc;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Builds the per-partition WHERE predicates exactly like Spark does from bounds + numPartitions.
class JdbcReadPlanner {
    private static final Logger log = Logger.getLogger(JdbcReadPlanner.class.getName());

    // Returns a list of [lo, hi) ranges; Spark turns each into WHERE col >= lo AND col < hi.
    List<long[]> planRanges(String column, long lower, long upper, int numPartitions) {
        List<long[]> ranges = new ArrayList<>();
        long stride = (upper - lower) / numPartitions;
        long cursor = lower;
        for (int i = 0; i < numPartitions; i++) {
            long lo = (i == 0) ? Long.MIN_VALUE : cursor;        // first slice catches < lower
            cursor += stride;
            long hi = (i == numPartitions - 1) ? Long.MAX_VALUE : cursor; // last catches >= upper
            ranges.add(new long[]{lo, hi});
            final int idx = i;
            final long flo = lo, fhi = hi;
            log.info(() -> "Partition " + idx + ": WHERE " + column + " >= " + flo + " AND " + column + " < " + fhi);
        }
        return ranges;
    }
}
