package com.bank.jdbc;

import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// Executes each range on its own thread (own connection), applies fetchsize.
class JdbcReader {
    private static final Logger log = Logger.getLogger(JdbcReader.class.getName());

    private final FakeJdbcTable table;

    JdbcReader(FakeJdbcTable table) { this.table = table; }

    int readParallel(List<long[]> ranges, int fetchsize) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(ranges.size());
        AtomicInteger total = new AtomicInteger();
        try {
            List<Future<Integer>> futures = new java.util.ArrayList<>();
            for (long[] r : ranges) {
                futures.add(pool.submit(() -> {
                    int lo = (int) Math.max(1, r[0]);
                    int hi = (int) Math.min(Integer.MAX_VALUE, r[1]);
                    String sql = "SELECT * FROM trades WHERE trade_id >= " + r[0] + " AND trade_id < " + r[1];
                    List<Integer> rows = table.query(sql, lo, hi, fetchsize);
                    log.fine(() -> "Connection read " + rows.size() + " rows for range");
                    return rows.size();
                }));
            }
            for (Future<Integer> f : futures) total.addAndGet(f.get());
        } finally {
            pool.shutdown();
        }
        log.info(() -> "Parallel read done: " + total.get() + " rows over " + ranges.size()
                + " connections, " + table.roundTrips() + " round trips (fetchsize=" + fetchsize + ")");
        return total.get();
    }
}
