package com.bank.jdbc;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Each task writes on its OWN connection and commits independently — no global transaction.
class JdbcWriter {
    private static final Logger log = Logger.getLogger(JdbcWriter.class.getName());

    private final FakeJdbcTable target;

    JdbcWriter(FakeJdbcTable target) { this.target = target; }

    // Simulates numWriteTasks partitions; failAtTask injects a mid-job failure.
    void writePartitioned(int totalRows, int numWriteTasks, int batchsize, int failAtTask) {
        int perTask = totalRows / numWriteTasks;
        for (int task = 0; task < numWriteTasks; task++) {
            if (task == failAtTask) {
                log.severe("Write task " + task + " FAILED — earlier tasks already COMMITTED (no global rollback)");
                throw new RuntimeException("Simulated write failure at task " + task);
            }
            List<int[]> batch = new ArrayList<>();
            for (int i = 0; i < perTask; i++) batch.add(new int[]{task, i});
            // Each task opens its own connection and commits its own batches.
            for (int start = 0; start < batch.size(); start += batchsize) {
                int end = Math.min(start + batchsize, batch.size());
                target.insertBatch(batch.subList(start, end));
            }
            final int t = task;
            log.info(() -> "Write task " + t + " committed " + perTask + " rows on its own connection");
        }
    }
}
