package com.bank.jdbc;

import java.util.List;
import java.util.logging.Logger;

public class JdbcTuningDemo {
    private static final Logger log = Logger.getLogger(JdbcTuningDemo.class.getName());

    public static void main(String[] args) throws Exception {
        int rowCount = 1_000_000;
        FakeJdbcTable source = new FakeJdbcTable(rowCount);

        // READ: plan 10 ranged queries, read in parallel with a healthy fetchsize.
        JdbcReadPlanner planner = new JdbcReadPlanner();
        List<long[]> ranges = planner.planRanges("trade_id", 1, 1_000_000, 10);
        JdbcReader reader = new JdbcReader(source);
        reader.readParallel(ranges, 10_000);
        log.info(() -> "Database saw " + source.executedQueryCount()
                + " parallel ranged queries (vs 1 for a single-connection read)");

        // Compare: tiny fetchsize causes many more round trips.
        FakeJdbcTable source2 = new FakeJdbcTable(rowCount);
        new JdbcReader(source2).readParallel(ranges, 10);
        log.warning(() -> "With fetchsize=10 the same read took " + source2.roundTrips() + " round trips");

        // WRITE: show no global transaction — a mid-job failure leaves partial data.
        FakeJdbcTable target = new FakeJdbcTable(0);
        JdbcWriter writer = new JdbcWriter(target);
        try {
            writer.writePartitioned(400_000, 4, 5_000, 2); // fail at task 2
        } catch (RuntimeException e) {
            log.severe(() -> "Job failed. Target already has " + target.writtenRows()
                    + " rows committed by tasks 0 and 1 — partial write, no rollback");
        }
    }
}
